# The Generated Files doctor check for the quickstart suite. Sourced by run.sh; it expects die and RESOURCES from there.

# After flisk up every resource has its .autogenerated/ files, so the Generated Files check passes and names them. The nightly run
# also tests the published `latest`, which may predate the check, so a report without it is skipped rather than failed.
check_generated_files() {
  local report
  report="$(flisk doctor --no-ping --json 2>/dev/null || true)"
  if ! printf '%s' "$report" | jq -e '.data.checks[] | select(.name == "Generated Files")' > /dev/null 2>&1; then
    echo "::notice::this flisk version has no Generated Files doctor check; skipping it"
    return 0
  fi
  printf '%s' "$report" | jq -e '.data.checks[] | select(.name == "Generated Files" and .didPass == true)' > /dev/null \
    || die "flisk doctor Generated Files check did not pass after flisk up: $(printf '%s' "$report" | jq -c '.data.checks[] | select(.name == "Generated Files")')"
  local resource
  for resource in "${RESOURCES[@]}"; do
    printf '%s' "$report" | jq -e --arg r "$resource" '.data.checks[] | select(.name == "Generated Files" and (.message | contains($r + ": ")))' > /dev/null \
      || echo "::warning::Generated Files did not list $resource"
  done
}
